
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_hjs_pbe_sol_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_hjs_pbe_sol", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.181456955011130e+00, -4.098784202646092e+00, -3.983004425892201e+00, -3.822757942482366e+00, -3.604695794549624e+00, -3.315109263594172e+00, -2.943783390996047e+00, -2.491002764532582e+00, -1.977139349736518e+00, -1.447794838095215e+00, -9.550280750045993e-01, -6.330416733036229e-01, -5.363908834106453e-01, -4.286112858056209e-01, -2.920117579470193e-01, -1.648531654465651e-01, -6.846347113762849e-02, -8.212400341513817e-03, -3.782012531312399e-05, -4.926777898592165e-08]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


